import{_ as s,H as u,f as a,i as e}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"专家推荐","description":"","frontmatter":{},"headers":[],"relativePath":"Rust程序设计（第2版）/专家推荐.md","filePath":"Rust程序设计（第2版）/专家推荐.md","lastUpdated":1795533925000}'),l={name:"Rust程序设计（第2版）/专家推荐.md"};function i(R,t,r,_,o,n){return u(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="专家推荐" tabindex="-1">专家推荐 <a class="header-anchor" href="#专家推荐" aria-label="Permalink to &quot;专家推荐&quot;">​</a></h1><p>这本书是深入探索 Rust 语言的权威指南，也是 Rust 编程思维的启示录。其最大价值是深入浅出地介绍了 Rust 的所有关键特性，从基本语法到并发和异步编程，每一章都配备了实用的示例代码和细致的解析。愿这本书引领你走进 Rust 的世界，体验其独特的魅力！</p><ul><li>——陈天，Tubi SVP</li></ul><p>非常高兴看到《Rust 程序设计（第 2 版）》引进出版。这本书对 Rust 知识做了全面而细致的介绍，特别花大量篇幅介绍了日常开发中用得最多的字符串、集合、迭代器等基础知识——对Rust 初学者来说，这无疑是非常重要的。预祝这本书的面世为 Rust 语言在国内的普及打开新局面。</p><ul><li>——唐刚（@Mike Tang），Rust 语言中文社区联合创始人</li></ul><p>多年前，我们就被 Rust 的无 GC 内存安全和零开销抽象所吸引。2019 年以来，随着 Rust 的成熟，我们开始逐渐用 Rust 重写项目，以 Kata Agent 为例，从 Go 换成 Rust 之后代码体积缩小到了之前的 1/20 以下，这对任何系统软件来说都是无法拒绝的。在我的团队里，优秀的内核和系统开发人员都会毫不拒绝从 C、Go 或其他语言转向 Rust，并边开发边学习。但是，Rust 被公认是一门上手难的语言，尤其是对于很多初学者，一本系统的好书才是最佳的入门阶梯。非常开心图灵公司引进《Rust 程序设计（第 2 版）》，相信这本书对于大家学习 Rust，乃至提高国内系统程序的安全性，都会有很大的帮助。</p><ul><li>——王旭，Kata Containers 项目联合发起人、开放基础设施基金会董事、蚂蚁集团容器基础设施团队负责人</li></ul><p>这本书是不可或缺的 Rust 编程资源，适合各个层次的开发者。书中深入解析了 Rust 的核心概念，如所有权、类型系统、并发等，配以实例代码，使得理解更为直观。如果你渴望深入探索 Rust，这本书将是你的最佳伙伴。</p><ul><li>——张汉东，资深 Rust 独立咨询师、Rust 中文社区布道者、《Rust 编程之道》作者</li></ul><p>我一直在寻找一本先实践后理论，能够提供有深度且实践性强的 Rust 编程知识的教程。当阅读这本书时，我发现了自己一直在寻找的东西。</p><ul><li>——张炎泼，分布式系统专家</li></ul>',11)])])}const c=s(l,[["render",i]]);export{d as __pageData,c as default};
